import{_ as a,o as t,c as r,a0 as o}from"./chunks/framework.DCluYYrN.js";const m=JSON.parse('{"title":"Что такое KernelSU?","description":"","frontmatter":{},"headers":[],"relativePath":"ru_RU/guide/what-is-kernelsu.md","filePath":"ru_RU/guide/what-is-kernelsu.md"}'),l={name:"ru_RU/guide/what-is-kernelsu.md"};function n(s,e,i,h,u,d){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="introduction" tabindex="-1">Что такое KernelSU? <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Что такое KernelSU? {#introduction}&quot;">​</a></h1><p>KernelSU - это root-решение для устройств Android GKI, работающее в режиме ядра и предоставляющее root-права пользовательским приложениям непосредственно в пространстве ядра.</p><h2 id="features" tabindex="-1">Особенности <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Особенности {#features}&quot;">​</a></h2><p>Основной особенностью KernelSU является то, что он <strong>основан на ядре</strong>. KernelSU работает в режиме ядра, поэтому он может предоставить интерфейс ядра, которого раньше не было. Например, мы можем добавить аппаратную точку останова любому процессу в режиме ядра; мы можем получить доступ к физической памяти любого процесса без чьего-либо ведома; мы можем перехватить любой syscall в пространстве ядра; и т.д.</p><p>Кроме того, KernelSU предоставляет <a href="./metamodule.html">систему metamodule</a>, которая является подключаемой архитектурой для управления модулями. В отличие от традиционных root-решений, которые встраивают логику монтирования в свое ядро, KernelSU делегирует это metamodules. Это позволяет устанавливать metamodules (например <a href="https://github.com/tiann/KernelSU/tree/main/userspace/meta-overlayfs" target="_blank" rel="noreferrer">meta-overlayfs</a>) для обеспечения бессистемных модификаций раздела <code>/system</code> и других разделов.</p><h2 id="how-to-use" tabindex="-1">Как использовать <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;Как использовать {#how-to-use}&quot;">​</a></h2><p>Пожалуйста, обратитесь к: <a href="./installation.html">Установка</a></p><h2 id="how-to-build" tabindex="-1">Как собрать <a class="header-anchor" href="#how-to-build" aria-label="Permalink to &quot;Как собрать {#how-to-build}&quot;">​</a></h2><p><a href="./how-to-build.html">Как собрать</a></p><h2 id="discussion" tabindex="-1">Обсуждение <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Обсуждение {#discussion}&quot;">​</a></h2><ul><li>Telegram: <a href="https://t.me/KernelSU" target="_blank" rel="noreferrer">@KernelSU</a></li></ul>',11)])])}const _=a(l,[["render",n]]);export{m as __pageData,_ as default};
